            skor = 1
        if skor:
            hasil.append((skor, r))
    hasil.sort(key=lambda x: -x[0])
    return [
        {k: r[k] for k in ("nama", "kategori", "min", "max", "acuan", "catatan", "sumber")}
        for _, r in hasil[:3]
